-- Czech Republic: ES/DE/FR milestone translations for the 3
-- milestones in migration 307. Hand-translated, not machine
-- copy-paste.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-b2g-accept-2016', 'es', 'Los poderes adjudicadores públicos deben aceptar facturas electrónicas EN 16931', 'A partir del 1 de octubre de 2016, la Ley n.º 134/2016 Coll. de Contratación Pública (artículo 221) transpuso la Directiva 2014/55/UE de la UE: los poderes adjudicadores centrales, regionales y locales no pueden rechazar una factura electrónica conforme presentada por un proveedor, en formato EDIFACT, UBL 2.1 o el formato nacional ISDOC, normalmente a través del portal Národní elektronický nástroj (NEN). Se trata únicamente de una obligación de recepción — nunca se exige a los proveedores que realmente emitan una factura electrónica, y no existe ningún mecanismo de supervisión que compruebe si lo hacen.', '["No se requiere ninguna acción para este hito histórico — se incluye como contexto de las entradas siguientes", "Los proveedores de organismos públicos checos pueden emitir facturas electrónicas en EDIFACT, UBL 2.1 o ISDOC de forma voluntaria a través de NEN, aunque nada lo exige"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-b2g-accept-2016', 'de', 'Öffentliche Auftraggeber müssen EN-16931-E-Rechnungen akzeptieren', 'Ab dem 1. Oktober 2016 setzte das Gesetz Nr. 134/2016 Coll. über die öffentliche Auftragsvergabe (Abschnitt 221) die EU-Richtlinie 2014/55/EU um: zentrale, regionale und lokale Auftraggeber dürfen eine konforme elektronische Rechnung eines Lieferanten im Format EDIFACT, UBL 2.1 oder dem nationalen ISDOC-Format nicht zurückweisen — üblicherweise übermittelt über das Portal Národní elektronický nástroj (NEN). Dies ist ausschließlich eine Empfangspflicht — Lieferanten müssen niemals tatsächlich eine E-Rechnung ausstellen, und es existiert kein Überwachungsmechanismus, der dies prüft.', '["Für diesen historischen Meilenstein ist noch keine Handlung erforderlich — er dient als Kontext für die folgenden Einträge", "Lieferanten tschechischer öffentlicher Stellen können E-Rechnungen in EDIFACT, UBL 2.1 oder ISDOC freiwillig über NEN ausstellen, auch wenn nichts dies vorschreibt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-b2g-accept-2016', 'fr', 'Les pouvoirs adjudicateurs publics doivent accepter les factures électroniques EN 16931', 'À compter du 1er octobre 2016, la loi n° 134/2016 Coll. relative aux marchés publics (article 221) a transposé la directive européenne 2014/55/UE : les pouvoirs adjudicateurs centraux, régionaux et locaux ne peuvent pas rejeter une facture électronique conforme soumise par un fournisseur, au format EDIFACT, UBL 2.1 ou au format national ISDOC, généralement via le portail Národní elektronický nástroj (NEN). Il s''agit uniquement d''une obligation de réception — rien n''oblige jamais un fournisseur à réellement émettre une facture électronique, et aucun mécanisme de suivi ne vérifie s''il le fait.', '["Aucune action n''est requise pour ce jalon historique — il est fourni à titre de contexte pour les entrées suivantes", "Les fournisseurs des organismes publics tchèques peuvent émettre des factures électroniques en EDIFACT, UBL 2.1 ou ISDOC volontairement via NEN, bien que rien ne l''impose"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-eet2-2027', 'es', 'EET 2.0 reactiva el reporte electrónico de ventas en tiempo real', 'A partir del 1 de enero de 2027, un régimen reactivado de Registro Electrónico de Ventas (EET 2.0) exigirá el reporte en tiempo real o casi real de las ventas presenciales B2C — pagos en efectivo, con tarjeta y por código QR por igual — a la Administración Tributaria checa, sustituyendo al modelo EET original (2016-2020 aproximadamente, derogado formalmente) que ahora se reactiva. Los pequeños autónomos con tributación a tanto alzado y una facturación anual inferior a 1.000.000 CZK pueden pagar un recargo para obtener la exención. El incumplimiento conlleva sanciones de hasta 500.000 CZK, y el Gobierno prevé entre 14.000 y 15.000 millones de CZK de ingresos fiscales adicionales anuales. La Cámara de Diputados ya ha aprobado la legislación; ahora pasa al Senado y, después, al presidente Petr Pavel para su firma definitiva. Se trata de una obligación de reporte de ventas/recibos en tiempo real, no de un mandato de facturación electrónica B2B estructurada — no hay formato de factura ni exigencia de intercambio de documentos entre comprador y vendedor.', '["Compruebe si su facturación anual está por debajo del umbral de exención de 1.000.000 CZK para pequeños autónomos", "Si tiene comercio minorista, hostelería o servicios presenciales, prepárese para el reporte electrónico de ventas en tiempo real — cuentan los pagos en efectivo, con tarjeta y por QR", "Vigile la aprobación del Senado y la firma presidencial — la fecha de entrada en vigor está confirmada en el proyecto de ley, pero la promulgación final aún no se ha firmado"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-eet2-2027', 'de', 'EET 2.0 belebt die elektronische Echtzeit-Umsatzmeldung wieder', 'Ab dem 1. Januar 2027 verlangt ein wiederbelebtes Regime der elektronischen Umsatzregistrierung (EET 2.0) die Echtzeit- oder nahezu Echtzeit-Meldung persönlicher B2C-Verkäufe — Bar-, Karten- und QR-Code-Zahlungen gleichermaßen — an die tschechische Steuerverwaltung und ersetzt damit das ursprüngliche EET-Modell (etwa 2016-2020, formell aufgehoben), das hiermit wiederbelebt wird. Kleine Pauschalsteuerpflichtige mit einem Jahresumsatz unter 1.000.000 CZK können gegen einen Zuschlag eine Befreiung erhalten. Ein Verstoß zieht Strafen von bis zu 500.000 CZK nach sich, und die Regierung rechnet mit zusätzlichen jährlichen Steuereinnahmen von 14-15 Milliarden CZK. Das Abgeordnetenhaus hat die Gesetzgebung bereits verabschiedet; sie geht nun an den Senat und anschließend zur endgültigen Unterschrift an Präsident Petr Pavel. Dies ist eine Pflicht zur Echtzeit-Umsatz-/Belegmeldung, keine strukturierte B2B-E-Rechnungspflicht — kein Rechnungsformat und keine Pflicht zum Dokumentenaustausch zwischen Käufer und Verkäufer.', '["Prüfen Sie, ob Ihr Jahresumsatz unter der Befreiungsschwelle von 1.000.000 CZK für Kleinunternehmer liegt", "Wenn Sie im stationären Einzelhandel, Gastgewerbe oder Dienstleistungsbereich tätig sind, planen Sie die elektronische Echtzeit-Umsatzmeldung ein — Bar-, Karten- und QR-Zahlungen zählen alle dazu", "Beobachten Sie die Verabschiedung im Senat und die Unterschrift des Präsidenten — das Inkrafttretensdatum ist im Gesetzentwurf festgelegt, die endgültige Verkündung ist aber noch nicht unterschrieben"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-eet2-2027', 'fr', 'EET 2.0 relance la déclaration électronique des ventes en temps réel', 'À compter du 1er janvier 2027, un régime relancé d''enregistrement électronique des ventes (EET 2.0) exigera la déclaration en temps réel ou quasi réel des ventes B2C en personne — paiements en espèces, par carte et par code QR — à l''administration fiscale tchèque, remplaçant le modèle EET original (environ 2016-2020, formellement abrogé) qu''il relance. Les petits entrepreneurs au régime forfaitaire dont le chiffre d''affaires annuel est inférieur à 1 000 000 CZK peuvent payer une majoration pour obtenir une exemption. Le non-respect entraîne des sanctions pouvant atteindre 500 000 CZK, et le gouvernement projette 14 à 15 milliards de CZK de recettes fiscales annuelles supplémentaires. La Chambre des députés a déjà adopté le texte ; il passe désormais au Sénat, puis au président Petr Pavel pour signature définitive. Il s''agit d''une obligation de déclaration des ventes/reçus en temps réel, non d''une obligation de facturation électronique B2B structurée — aucun format de facture, ni exigence d''échange de documents entre acheteur et vendeur.', '["Vérifiez si votre chiffre d''affaires annuel est inférieur au seuil d''exemption de 1 000 000 CZK pour les petits entrepreneurs", "Si vous exercez dans le commerce de détail, l''hôtellerie-restauration ou les services en personne, préparez-vous à la déclaration électronique des ventes en temps réel — les paiements en espèces, par carte et par QR sont tous concernés", "Surveillez l''adoption par le Sénat et la signature présidentielle — la date d''entrée en vigueur est confirmée dans le projet de loi, mais la promulgation définitive n''est pas encore signée"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-vida-2030', 'es', 'Entra en vigor el reporte digital transfronterizo B2B de ViDA', 'Con independencia de que la República Checa promulgue algún día un mandato nacional de facturación electrónica B2B — no existe ninguno ni se ha propuesto actualmente —, la directiva del IVA en la Era Digital (ViDA) de la UE exige capacidad de facturación electrónica estructurada y reporte digital para las operaciones B2B intracomunitarias a partir del 1 de julio de 2030 — derecho de la UE confirmado (Directiva (UE) 2025/516 del Consejo).', '["Las empresas que comercian transfronterizamente dentro de la UE deben prepararse para la capacidad de facturación electrónica conforme con EN 16931 y de reporte en esta fecha, con independencia de cualquier mandato nacional checo"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-vida-2030', 'de', 'ViDAs grenzüberschreitende B2B-Digitalmeldung tritt in Kraft', 'Unabhängig davon, ob Tschechien jemals eine inländische B2B-E-Rechnungspflicht erlässt — derzeit existiert keine und ist keine vorgeschlagen —, verlangt die EU-Richtlinie VAT in the Digital Age (ViDA) ab dem 1. Juli 2030 strukturierte E-Rechnungs- und digitale Meldefähigkeit für innergemeinschaftliche B2B-Umsätze — bestätigtes EU-Recht (Richtlinie (EU) 2025/516 des Rates).', '["Unternehmen, die grenzüberschreitend innerhalb der EU Handel betreiben, sollten bis zu diesem Datum EN-16931-konforme E-Rechnungs- und Meldefähigkeit einplanen, unabhängig von einer etwaigen inländischen tschechischen Pflicht"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cz-vida-2030', 'fr', 'L''obligation transfrontalière de déclaration numérique B2B de ViDA entre en vigueur', 'Indépendamment du fait que la République tchèque adopte un jour une obligation nationale de facturation électronique B2B — aucune n''existe ni n''est actuellement proposée —, la directive européenne TVA à l''ère numérique (ViDA) exige une capacité de facturation électronique structurée et de déclaration numérique pour les transactions B2B intracommunautaires à partir du 1er juillet 2030 — droit de l''UE confirmé (directive (UE) 2025/516 du Conseil).', '["Les entreprises commerçant à l''échelle transfrontalière au sein de l''UE devraient prévoir une capacité de facturation électronique conforme à l''EN 16931 et de déclaration à cette date, indépendamment de toute obligation nationale tchèque"]');
